auto view = std::make_unique<View>();
buckets_out.clear();
buckets_out.reserve(num_buckets);

const float circle = 1.0f;
const float partition_step = circle / (num_buckets * partitions_per_bucket);

for (int i = 0; i < num_buckets; ++i) {
    std::string bucket_name = "bucket_" + std::to_string(i);
    std::vector<float> points;

    for (int j = 0; j < partitions_per_bucket; ++j) {
        float point = (i * partitions_per_bucket + j) * partition_step;
        points.push_back(point);
    }

    auto bucket = std::make_shared<Bucket>(bucket_name, points);
    buckets_out.push_back(bucket);
    view->Add(bucket);
}

return std::make_unique<std::map<float, BucketPtr>>(view->partition_to_bucket_.begin(),
                                                   view->partition_to_bucket_.end());

